impl Solution {
    pub fn count_routes(locations: Vec<i32>, start: i32, finish: i32, fuel: i32) -> i32 {
        const MOD: i32 = 1000000007;
        let n = locations.len() as i32;
        let mut dp = vec![vec![vec![0; fuel as usize + 1]; n as usize]; n as usize];
        dp[start as usize][finish as usize][0] = 1;

        for remaining_fuel in 1..=fuel {
            for current in 0..n {
                for next in 0..n {
                    if current == next {
                        dp[current as usize][next as usize][remaining_fuel as usize] =
                            dp[current as usize][next as usize][remaining_fuel as usize - 1];
                    } else {
                        let cost = (locations[current as usize] as i32 - locations[next as usize] as i32).abs();
                        if cost <= remaining_fuel {
                            dp[current as usize][next as usize][remaining_fuel as usize] =
                                (dp[current as usize][next as usize][remaining_fuel as usize] +
                                 dp[next as usize][current as usize][remaining_fuel as usize - cost as usize]) % MOD;
                        }
                        dp[current as usize][next as usize][remaining_fuel as usize] =
                            (dp[current as usize][next as usize][remaining_fuel as usize] +
                             dp[current as usize][next as usize][remaining_fuel as usize - 1]) % MOD;
                    }
                }
            }
        }

        dp[start as usize][finish as usize][fuel as usize]
    }
}
